1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Scenario = {
12	  customer: Customer;
13	  steps: { op: string; items: Item[] }[];
14	};
15	
16	export type ScenarioResult = {
17	  results: { premium: number }[];
18	};
19	
20	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	};
28	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
29	const CURSE_SURCHARGE_PERCENT = 50;
30	const HIGH_ENCHANTMENT_THRESHOLD = 5;
31	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
32	const LOYALTY_THRESHOLD_YEARS = 2;
33	const LOYALTY_DISCOUNT_PERCENT = 20;
34	const FOLLOWUP_DISCOUNT_PERCENT = 15;
35	const PROCESSING_FEE = 5;
36	
37	const percentOf = (amount: number, percent: number): number =>
38	  (amount * percent) / 100;
39	
40	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	
45	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
46	const countAlikeItems = (items: Item[]): Map<string, number> =>
47	  items.reduce(
48	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
49	    new Map<string, number>(),
50	  );
51	
52	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
53	
54	const basePremiumForAlikeItems = (type: string, count: number): number =>
55	  formsBuildingBlock(count)
56	    ? BLOCK_BASE_PREMIUM
57	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
58	
59	const policyBasePremium = (items: Item[]): number =>
60	  [...countAlikeItems(items)].reduce(
61	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
62	    0,
63	  );
64	
65	const itemBasePremium = (item: Item): number =>
66	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
67	
68	const isHighlyEnchanted = (item: Item): boolean =>
69	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
70	
71	/** Item-specific surcharges stack additively. */
72	const itemSurchargePercent = (item: Item): number =>
73	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
74	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
75	
76	/**
77	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
78	 * premium — unlike policy-wide modifiers, which apply to the policy base.
79	 */
80	const totalItemSurcharges = (items: Item[]): number =>
81	  items.reduce(
82	    (total, item) =>
83	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
84	    0,
85	  );
86	
87	const isLongStanding = (customer: Customer): boolean =>
88	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
89	
90	/**
91	 * The net of all policy-wide percentages. Policy-wide modifiers are
92	 * percentages of the POLICY base premium — unlike item-specific modifiers,
93	 * which apply to the affected item's own base. The net is negative when the
94	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
95	 */
96	const netPolicyAdjustmentPercent = (
97	  customer: Customer,
98	  precedingQuotes: number,
99	): number =>
100	  FIRST_INSURANCE_SURCHARGE_PERCENT -
101	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
102	  (precedingQuotes > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
103	
104	const policyAdjustment = (
105	  policyBase: number,
106	  customer: Customer,
107	  precedingQuotes: number,
108	): number =>
109	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingQuotes));
110	
111	const quotePremium = (
112	  items: Item[],
113	  customer: Customer,
114	  precedingQuotes: number,
115	): number => {
116	  const basePremium = policyBasePremium(items);
117	  return roundInMHPCOsFavour(
118	    basePremium +
119	      totalItemSurcharges(items) +
120	      policyAdjustment(basePremium, customer, precedingQuotes) +
121	      PROCESSING_FEE,
122	  );
123	};
124	
125	/**
126	 * Every step is quoted. `step.op` is not yet consulted — "quote" is the only
127	 * operation exercised so far; claims will need to dispatch on it.
128	 */
129	export const runScenario = (scenario: Scenario): ScenarioResult => ({
130	  results: scenario.steps.map((step, precedingQuotes) => ({
131	    premium: quotePremium(step.items, scenario.customer, precedingQuotes),
132	  })),
133	});
