  customer: Customer,
  precedingQuotes: number,
): number =>
  FIRST_INSURANCE_SURCHARGE_PERCENT -
  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
  (precedingQuotes > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);

